using System;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace SlopStudio {
 public static class VideoDecoder {
  public static string FfmpegPath(){string local=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"ffmpeg.exe");if(File.Exists(local))return local;string configured=Environment.GetEnvironmentVariable("SLOPSTUDIO_FFMPEG");return !String.IsNullOrWhiteSpace(configured)?configured:"ffmpeg.exe";}
  public static Bitmap Frame(string file,double seconds){if(file.IndexOf('"')>=0)throw new ArgumentException("Invalid movie path.");var start=new ProcessStartInfo(FfmpegPath(),"-nostdin -hide_banner -loglevel error -ss "+Math.Max(0,seconds).ToString("0.000",System.Globalization.CultureInfo.InvariantCulture)+" -i \""+file+"\" -frames:v 1 -vf scale=960:540:force_original_aspect_ratio=decrease -f image2pipe -c:v bmp pipe:1"){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true};try{using(var process=Process.Start(start)){var errors=process.StandardError.ReadToEndAsync();using(var bytes=new MemoryStream()){var copy=process.StandardOutput.BaseStream.CopyToAsync(bytes);if(!process.WaitForExit(10000)){process.Kill();throw new TimeoutException("Movie frame decode timed out.");}copy.Wait();if(process.ExitCode!=0||bytes.Length==0)throw new InvalidDataException(errors.Result.Trim().Length==0?"Movie contains no decodable video frame at this position.":errors.Result.Trim());bytes.Position=0;using(var image=Image.FromStream(bytes))return new Bitmap(image);}}}catch(System.ComponentModel.Win32Exception){throw new InvalidOperationException("Movie import requires FFmpeg. Install ffmpeg on PATH, set SLOPSTUDIO_FFMPEG, or place ffmpeg.exe beside SlopStudio.exe.");}}
 }
 public sealed class VideoPreviewForm:Form {
  private readonly PictureBox _picture=new PictureBox{Dock=DockStyle.Fill,SizeMode=PictureBoxSizeMode.Zoom,BackColor=Color.FromArgb(16,16,16)};private readonly Label _position=new Label{Dock=DockStyle.Bottom,Height=28,ForeColor=Color.Gainsboro,BackColor=Color.FromArgb(40,40,42),TextAlign=ContentAlignment.MiddleCenter};private readonly Timer _timer=new Timer{Interval=165};private bool _busy;private double _last=Double.MinValue;public Func<double> Position;public string MoviePath;
  public VideoPreviewForm(){Text="Movie Preview";Size=new Size(840,520);StartPosition=FormStartPosition.CenterParent;Controls.Add(_picture);Controls.Add(_position);_timer.Tick+=async delegate{if(_busy||Position==null||String.IsNullOrEmpty(MoviePath))return;double seconds=Position();if(Math.Abs(seconds-_last)<.12)return;_last=seconds;_busy=true;try{var frame=await Task.Factory.StartNew(()=>VideoDecoder.Frame(MoviePath,seconds));if(IsDisposed){frame.Dispose();return;}var old=_picture.Image;_picture.Image=frame;if(old!=null)old.Dispose();_position.Text=TimeSpan.FromSeconds(seconds).ToString(@"hh\:mm\:ss\.fff")+"  ·  "+UiText.Translate("Synchronized movie preview");}catch(Exception ex){if(!IsDisposed)_position.Text=UiText.Translate(ex.Message);}finally{_busy=false;}};Shown+=delegate{UiText.Apply(this);_timer.Start();};FormClosed+=delegate{_timer.Stop();_timer.Dispose();if(_picture.Image!=null)_picture.Image.Dispose();};}
 }
 public sealed partial class MainForm {
  private async void ImportMovie(string file){await ImportMovieAsync(file);}
  private async Task ImportMovieAsync(string file){if(_recording||_importing)return;_importing=true;try{_statusLabel.Text=UiText.Translate("Importing movie…");using(var check=await Task.Factory.StartNew(()=>VideoDecoder.Frame(file,0))){}await new UiDispatch(this);double start=_cursorBeat;var after=_project.Studio.Copy();after.Video=new VideoReference{Path=Path.GetFullPath(file),StartBeat=start};_history.Execute(_project,new SetStudioCommand("Import movie reference",_project.Studio,after));try{string audio=await Task.Factory.StartNew(()=>MediaImport.Decode(file,Path.Combine(Path.GetDirectoryName(SettingsStore.DefaultPath),"Imported Media")));await new UiDispatch(this);var track=ProjectFactory.CreateTrack(Path.GetFileNameWithoutExtension(file)+" — Movie Audio",TrackType.Audio);var region=ProjectFactory.CreateRegion(Path.GetFileNameWithoutExtension(file),start,Math.Max(.25,WaveAudio.Inspect(audio).DurationSeconds*_project.Tempo/60));region.MediaPath=audio;track.Regions.Add(region);_history.Execute(_project,new AddTrackCommand(track,_project.Tracks.Count));}catch(Exception ex){ErrorLog.Write("Movie audio stream",ex);_statusLabel.Text=UiText.Translate("Movie loaded; audio extraction unavailable")+": "+ex.Message;}RefreshState();ShowMovie();}catch(Exception ex){ShowError("Movie import failed",ex);}finally{_importing=false;}}
  private void ShowMovie(){if(_project.Studio.Video==null)return;if(_videoWindow!=null&&!_videoWindow.IsDisposed){_videoWindow.Activate();return;}_videoWindow=new VideoPreviewForm{MoviePath=_project.Studio.Video.Path,Position=()=>Math.Max(0,(_cursorBeat-_project.Studio.Video.StartBeat)*60/_project.Tempo)};_videoWindow.Show(this);}
 }
}
